"""Repository-local provider guards generated by explicit AIWorkHub init."""

from __future__ import annotations

import json
import os
import tempfile
from pathlib import Path
from typing import Any

from . import agent_tool_instructions as instructions
from .runtime_adapters import (
    CLAUDE_RAW_DISCOVERY_DENIES,
    CLAUDE_RAW_DISCOVERY_TOOL_DENIES,
    CLAUDE_WORKER_RAW_EDITOR_DENIES,
    CLAUDE_WORKER_VALIDATION_SHELL_DENIES,
    claude_disallowed_tools,
)


CLAUDE_SETTINGS_REL = Path(".claude/settings.json")
CLAUDE_TOOL_GUARD_HOOK_REL = Path(".claude/hooks/aiworkhub_tool_guard.py")
_TOOL_GUARD_SOURCE = Path(__file__).with_name("tool_guard_hook.py")
_TOOL_GUARD_MARKER = "aiworkhub_tool_guard.py"
_TOOL_GUARD_MATCHER = "Bash|PowerShell|Read|Edit|Write"
# The hook runs the tree's copy of the script with whatever ``python`` the
# session resolves. ``python <missing file>`` exits 2, and 2 is the exit code
# that BLOCKS a PreToolUse call, so the command looks the script up itself and
# runs it only when it exists: a tree without it loses the guard, not its tools.
_TOOL_GUARD_LOCATE = (
    "import os,runpy,sys;"
    "p=os.path.join(os.environ.get('CLAUDE_PROJECT_DIR') or os.getcwd(),"
    "'.claude','hooks','aiworkhub_tool_guard.py');"
)
_TOOL_GUARD_RUN = "os.path.isfile(p) and runpy.run_path(p,run_name='__main__')"
CLAUDE_TOOL_GUARD_COMMAND = 'python -c "' + _TOOL_GUARD_LOCATE + _TOOL_GUARD_RUN + '"'
CLAUDE_TOOL_GUARD_REMINDER_COMMAND = (
    'python -c "' + _TOOL_GUARD_LOCATE + "sys.argv=[p,'--reminder'];" + _TOOL_GUARD_RUN + '"'
)


class ProviderGuardError(RuntimeError):
    pass


def claude_settings_deny(*, read_only: bool) -> tuple[str, ...]:
    """The ``permissions.deny`` list a Claude tree gets for THIS role.

    ``runtime_adapters.claude_disallowed_tools`` already answers this question
    for the provider argv: a build worker is denied raw discovery in every form
    because Source Graph is its discovery path, and a read-only reviewer keeps
    the raw SHELL denies but is granted the bounded native ``Grep``/``Glob``
    instead (measured: 1,080 denied Bash calls, 25% of every reviewer Bash call,
    across 181 of 242 runs).

    That grant was inert. A reviewer runs inside a git worktree created by
    ``worker_workspace.create_workspace``, so it checks out the repository's own
    tracked ``.claude/settings.json`` -- and a project ``permissions.deny`` wins
    over an argv ``--allowedTools`` entry. The reviewer therefore inherited the
    build worker's deny and went on burning turns on refusals.

    So the settings value is derived from the SAME function as the argv. The two
    enforcement surfaces cannot disagree about a role, and the build worker's
    rule is untouched: for ``read_only=False`` this is exactly
    ``CLAUDE_RAW_DISCOVERY_DENIES``.

    ONE deliberate subtraction: the raw validation spellings
    (``CLAUDE_WORKER_VALIDATION_SHELL_DENIES``) are a LAUNCH rule, not a tree
    rule, so they never reach a ``.claude/settings.json``.  Two measured facts
    decide it.  First, Claude Bash rules are prefix matches, so
    ``Bash(pytest *)`` cannot match ``<python> -m pytest`` -- the form every
    invocation in this repository actually uses -- so the settings entry buys
    nothing against the real spelling.  Second, this file is TRACKED: writing it
    there constrains every human session, every Claude Code session and the
    manager seat, none of whom are the build workers the rule aims at.  A rule
    that is ineffective where it aims and effective where it does not aim is
    removed, not kept.  The argv deny stays (it belongs to the launch, which is
    where the role actually exists) and the worker runtime policy states the
    rule in words, which is the part that reaches the worker.

    The SECOND subtraction is the raw file editor
    (``CLAUDE_WORKER_RAW_EDITOR_DENIES``), for the same reason and with more
    force.  A build worker must route a change to an existing file through
    ``semantic_edit_prepare``/``_apply``, and the launch argv denies ``Edit``
    to make that real rather than merely written.  But this file is TRACKED,
    and a worker worktree checks out exactly these bytes -- so putting
    ``Edit`` here would ALSO deny the raw editor to every human session and
    every interactive Claude Code session opened on this repository, none of
    whom are the build workers the rule aims at.  The role exists at the
    launch, so the deny stays at the launch.
    """

    denied = claude_disallowed_tools(read_only=bool(read_only))
    launch_only = frozenset(
        CLAUDE_WORKER_VALIDATION_SHELL_DENIES + CLAUDE_WORKER_RAW_EDITOR_DENIES
    )
    return tuple(item for item in denied if item not in launch_only)


def _is_legacy_ai_tool_command(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    return "AITools/source_graph.py" in value or "AITools/cgraph.py" in value


def _remove_legacy_pretool_hooks(payload: dict[str, Any]) -> bool:
    hooks = payload.get("hooks")
    if not isinstance(hooks, dict):
        return False
    rows = hooks.get("PreToolUse")
    if not isinstance(rows, list):
        return False
    kept: list[Any] = []
    changed = False
    for row in rows:
        nested = row.get("hooks") if isinstance(row, dict) else None
        legacy = isinstance(nested, list) and any(
            isinstance(item, dict) and _is_legacy_ai_tool_command(item.get("command"))
            for item in nested
        )
        if legacy:
            changed = True
        else:
            kept.append(row)
    if changed:
        if kept:
            hooks["PreToolUse"] = kept
        else:
            hooks.pop("PreToolUse", None)
        if not hooks:
            payload.pop("hooks", None)
    return changed


def _atomic_write(path: Path, data: bytes | str) -> None:
    if isinstance(data, str):
        # The newline translation a text-mode handle performs, made explicit.
        data = data.replace("\n", os.linesep).encode("utf-8")
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
        os.replace(temporary, path)
    finally:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass


def _tool_guard_hook_rows() -> tuple[tuple[str, dict[str, Any]], ...]:
    """The managed ``(event, row)`` pairs, built fresh on every call."""

    def row(matcher: str, command: str) -> dict[str, Any]:
        return {
            "matcher": matcher,
            "hooks": [{"type": "command", "command": command, "timeout": 10}],
        }

    return (
        ("PreToolUse", row(_TOOL_GUARD_MATCHER, CLAUDE_TOOL_GUARD_COMMAND)),
        ("SessionStart", row("compact", CLAUDE_TOOL_GUARD_REMINDER_COMMAND)),
    )


def _is_tool_guard_hook(item: Any) -> bool:
    return isinstance(item, dict) and _TOOL_GUARD_MARKER in str(item.get("command") or "")


def _install_tool_guard_hooks(payload: dict[str, Any]) -> bool:
    """Idempotently install the managed tool-guard hook rows; owner hooks are kept.

    A hook is managed when its command names ``aiworkhub_tool_guard.py``. Every
    managed hook is dropped and ONE canonical row goes back where the first of
    them was (appended when there was none), so a re-apply replaces in place and
    never duplicates. A row an owner wrote around a managed hook keeps the rest.
    """

    hooks = payload.setdefault("hooks", {})
    if not isinstance(hooks, dict):
        raise ProviderGuardError("claude_hooks_object_required")
    changed = False
    for event, managed in _tool_guard_hook_rows():
        rows = hooks.get(event)
        if rows is None:
            rows = []
        if not isinstance(rows, list):
            raise ProviderGuardError(f"claude_hooks_list_required:{event}")
        merged: list[Any] = []
        slot: int | None = None
        for row in rows:
            nested = row.get("hooks") if isinstance(row, dict) else None
            if not isinstance(nested, list) or not any(map(_is_tool_guard_hook, nested)):
                merged.append(row)
                continue
            if slot is None:
                slot = len(merged)
            owned = [item for item in nested if not _is_tool_guard_hook(item)]
            if owned:
                merged.append({**row, "hooks": owned})
        merged.insert(len(merged) if slot is None else slot, managed)
        if merged != rows:
            hooks[event] = merged
            changed = True
    return changed


def _install_tool_guard_script(root: Path) -> bool:
    """Write the hook script the settings run when it is absent or not this module."""

    path = (root / CLAUDE_TOOL_GUARD_HOOK_REL).resolve()
    if not path.is_relative_to(root):
        raise ProviderGuardError("claude_tool_guard_path_escape")
    try:
        source = _TOOL_GUARD_SOURCE.read_bytes()
    except OSError as exc:
        raise ProviderGuardError(f"claude_tool_guard_source_unreadable:{exc}") from exc
    try:
        if path.is_file() and path.read_bytes() == source:
            return False
    except OSError:
        pass
    _atomic_write(path, source)
    return True


def _merge_claude_settings(
    path: Path, *, read_only: bool = False
) -> tuple[dict[str, Any], bool]:
    if path.exists():
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise ProviderGuardError(f"claude_settings_invalid:{exc}") from exc
        if not isinstance(payload, dict):
            raise ProviderGuardError("claude_settings_object_required")
    else:
        payload = {}
    permissions = payload.setdefault("permissions", {})
    if not isinstance(permissions, dict):
        raise ProviderGuardError("claude_permissions_object_required")
    changed = _remove_legacy_pretool_hooks(payload)
    if _install_tool_guard_hooks(payload):
        changed = True
    allow = permissions.get("allow")
    if allow is not None:
        if not isinstance(allow, list) or any(not isinstance(item, str) for item in allow):
            raise ProviderGuardError("claude_permissions_allow_string_list_required")
        filtered_allow = [item for item in allow if not _is_legacy_ai_tool_command(item)]
        if filtered_allow != allow:
            permissions["allow"] = filtered_allow
            changed = True
    deny = permissions.setdefault("deny", [])
    if not isinstance(deny, list) or any(not isinstance(item, str) for item in deny):
        raise ProviderGuardError("claude_permissions_deny_string_list_required")
    required = claude_settings_deny(read_only=read_only)
    # A reviewer tree is a git worktree of this repository, so it arrives with
    # the canonical tracked deny already in it. Merging alone would leave the
    # build worker's ``Grep``/``Glob`` entries in place and the argv grant inert,
    # so the entries this role must not inherit are dropped explicitly. Only the
    # native tool denies are role-scoped: the raw SHELL forms stay denied for
    # every role, and nothing a repository owner wrote is touched.
    # The launch-only validation denies are surrendered for EVERY role, so a
    # tree that inherited them from an earlier provisioning is repaired rather
    # than left carrying a rule that belongs to the argv (see
    # ``claude_settings_deny``).
    surrendered = (
        frozenset(CLAUDE_RAW_DISCOVERY_TOOL_DENIES) - frozenset(required)
    ) | frozenset(CLAUDE_WORKER_VALIDATION_SHELL_DENIES)
    merged = [item for item in deny if item not in surrendered]
    for item in required:
        if item not in merged:
            merged.append(item)
    changed = changed or merged != deny
    permissions["deny"] = merged
    return payload, changed


def apply_repository_guards(repo_root: Path, *, read_only: bool = False) -> dict[str, Any]:
    """Idempotently install all provider instructions, Claude hard denies and the tool guard.

    ``read_only`` names the ROLE the tree is being provisioned for and defaults
    to the writing one, so a caller that does not think about roles provisions a
    build worker's full deny -- the direction that can only be too strict.
    """

    root = repo_root.resolve()
    changed: list[str] = []
    for provider in instructions.PROVIDERS:
        path = (root / provider).resolve()
        if not path.is_relative_to(root):
            raise ProviderGuardError(f"provider_path_escape:{provider}")
        owner = path.read_text(encoding="utf-8") if path.exists() else ""
        plan = instructions.build_apply_plan(
            provider, owner, manager_edit_script=instructions.manager_edit_script_present(root)
        )
        if not plan["ok"]:
            raise ProviderGuardError(f"provider_policy_invalid:{provider}:{plan['reason']}")
        if plan["planned_text"] != owner:
            _atomic_write(path, str(plan["planned_text"]))
            changed.append(provider)

    claude_path = (root / CLAUDE_SETTINGS_REL).resolve()
    if not claude_path.is_relative_to(root):
        raise ProviderGuardError("claude_settings_path_escape")
    settings, settings_changed = _merge_claude_settings(claude_path, read_only=read_only)
    if settings_changed or not claude_path.exists():
        _atomic_write(
            claude_path,
            json.dumps(settings, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        )
        changed.append(CLAUDE_SETTINGS_REL.as_posix())
    if _install_tool_guard_script(root):
        changed.append(CLAUDE_TOOL_GUARD_HOOK_REL.as_posix())

    return {
        "ok": True,
        "changed": changed,
        "managed_providers": [*instructions.PROVIDERS, CLAUDE_SETTINGS_REL.as_posix()],
        "read_only": bool(read_only),
        "claude_raw_discovery_denied": list(claude_settings_deny(read_only=read_only)),
    }


def apply_workspace_guards(workspace_root: Path, *, read_only: bool) -> dict[str, Any]:
    """Rewrite ONE provisioned worktree's Claude settings and tool-guard hook for its role.

    :func:`apply_repository_guards` provisions the canonical repository at init.
    A worker or reviewer, though, does not run there: it runs in a git worktree
    that ``worker_workspace.create_workspace`` checked out, which inherits the
    canonical tracked settings file verbatim. That inheritance is what made the
    reviewer's native-search grant inert.

    This touches the settings file and the tool-guard hook script ONLY -- never
    a provider instruction file -- because those are already correct in the
    checkout and rewriting them would put unrelated paths into the candidate
    delta a reviewer must not carry. The settings hooks run the script from the
    tree, so a checkout whose copy is missing or stale gets this module's bytes.

    ``baseline_paths`` names the exact repository-relative paths this may write.
    A caller provisioning a workspace must fold them into the workspace baseline
    it snapshots, or the rewrite reads back as a candidate edit the reviewer made.
    """

    root = Path(workspace_root).resolve()
    claude_path = (root / CLAUDE_SETTINGS_REL).resolve()
    if not claude_path.is_relative_to(root):
        raise ProviderGuardError("claude_settings_path_escape")
    settings, settings_changed = _merge_claude_settings(claude_path, read_only=read_only)
    changed: list[str] = []
    if settings_changed or not claude_path.exists():
        _atomic_write(
            claude_path,
            json.dumps(settings, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        )
        changed.append(CLAUDE_SETTINGS_REL.as_posix())
    if _install_tool_guard_script(root):
        changed.append(CLAUDE_TOOL_GUARD_HOOK_REL.as_posix())
    return {
        "ok": True,
        "read_only": bool(read_only),
        "changed": changed,
        "baseline_paths": [
            CLAUDE_SETTINGS_REL.as_posix(),
            CLAUDE_TOOL_GUARD_HOOK_REL.as_posix(),
        ],
        "deny": list(claude_settings_deny(read_only=read_only)),
    }


__all__ = [
    "CLAUDE_SETTINGS_REL",
    "CLAUDE_TOOL_GUARD_COMMAND",
    "CLAUDE_TOOL_GUARD_HOOK_REL",
    "CLAUDE_TOOL_GUARD_REMINDER_COMMAND",
    "ProviderGuardError",
    "apply_repository_guards",
    "apply_workspace_guards",
    "claude_settings_deny",
]
